window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-435aa6cd5894fb53"]={"versions": [{"id": "FIG-435aa6cd5894fb53", "releases": ["R1.5.1", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_DeterminationOfAction</code>) aus der Spezifikation des Health Monitoring (AUTOSAR Adaptive Platform). Das Diagramm modelliert die strukturellen Zusammenhänge und Zuordnungen für die Aktionsbestimmung (<code>Determination of Action</code>) auf Basis von Auswertungsregeln (<code>Rule</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>DeterminationOfAction</strong>: Wurzelelement bzw. Kontextentität; steht über eine Kompositionsbeziehung (schwarze Raute) mit <code>ActionList</code> in Verbindung.</li>\n<li><strong>Rule</strong>: Repräsentiert die logische Bewertungsregel; verknüpft mit <code>ActionList</code> über zwei gerichtete Assoziationen:</li>\n<li><code>TrueActionList</code> (Kardinalität <code>0..1</code> an <code>ActionList</code>): Aktionsliste bei positivem Regelergebnis.</li>\n<li><code>FalseActionList</code> (Kardinalität <code>0..1</code> an <code>ActionList</code>): Aktionsliste bei negativem Regelergebnis.</li>\n<li><strong>ActionList</strong>: Liste auszuführender Aktionen; referenziert über eine gerichtete Assoziation <code>ActionItem</code> und besitzt eine Abhängigkeit (gestrichelter Pfeil) zum Enumerationstyp <code>ActionListExecutionEnum</code>.</li>\n<li><strong>ActionItem</strong>: Einzelne konkrete Aktion innerhalb der Aktionsliste.</li>\n<li><strong>«enumeration» ActionListExecutionEnum</strong>: Steuert den Ausführungsmodus der Aktionsliste mit den Literalwerten:</li>\n<li><code>triggeredOnChange</code></li>\n<li><code>triggeredOnEvaluation</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Kontrollflusskanten. Zur Laufzeit erfolgt die Auswertung einer <code>Rule</code>: Abhängig vom Wahrheitswert des Auswertungsergebnisses wird entweder die assoziierte <code>TrueActionList</code> oder <code>FalseActionList</code> bestimmt (sofern <code>0..1</code> instantiiert). Das Enumerationsattribut <code>ActionListExecutionEnum</code> legt fest, ob die in <code>ActionList</code> enthaltenen <code>ActionItem</code>-Elemente bei jeder Auswertung (<code>triggeredOnEvaluation</code>) oder ausschließlich bei einer Statusänderung des Ergebnisses (<code>triggeredOnChange</code>) getriggert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die metamodellierte Konfigurationsstruktur für die Fehlerreaktion im Health Monitoring. Entwickler und Integratoren müssen sicherstellen, dass Regeln gültige Referenzen auf Aktionslisten (<code>0..1</code>) besitzen und das Triggerverhalten (<code>ActionListExecutionEnum</code>) passend zur geforderten Reaktionszeit und Systemlast (flankengetriggert vs. periodisch/auswertungsbasiert) parametriert wird.</p>"}, {"id": "FIG-c22c3dab6dfed574", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_DeterminationOfAction</code>) aus der Spezifikation des Health Monitoring (AUTOSAR Adaptive Platform). Das Diagramm modelliert die strukturellen Zusammenhänge und Zuordnungen für die Aktionsbestimmung (<code>Determination of Action</code>) auf Basis von Auswertungsregeln (<code>Rule</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>DeterminationOfAction</strong>: Wurzelelement bzw. Kontextentität; steht über eine Kompositionsbeziehung (schwarze Raute) mit <code>ActionList</code> in Verbindung.</li>\n<li><strong>Rule</strong>: Repräsentiert die logische Bewertungsregel; verknüpft mit <code>ActionList</code> über zwei gerichtete Assoziationen:</li>\n<li><code>TrueActionList</code> (Kardinalität <code>0..1</code> an <code>ActionList</code>): Aktionsliste bei positivem Regelergebnis.</li>\n<li><code>FalseActionList</code> (Kardinalität <code>0..1</code> an <code>ActionList</code>): Aktionsliste bei negativem Regelergebnis.</li>\n<li><strong>ActionList</strong>: Liste auszuführender Aktionen; referenziert über eine gerichtete Assoziation <code>ActionItem</code> und besitzt eine Abhängigkeit (gestrichelter Pfeil) zum Enumerationstyp <code>ActionListExecutionEnum</code>.</li>\n<li><strong>ActionItem</strong>: Einzelne konkrete Aktion innerhalb der Aktionsliste.</li>\n<li><strong>«enumeration» ActionListExecutionEnum</strong>: Steuert den Ausführungsmodus der Aktionsliste mit den Literalwerten:</li>\n<li><code>triggeredOnChange</code></li>\n<li><code>triggeredOnEvaluation</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Kontrollflusskanten. Zur Laufzeit erfolgt die Auswertung einer <code>Rule</code>: Abhängig vom Wahrheitswert des Auswertungsergebnisses wird entweder die assoziierte <code>TrueActionList</code> oder <code>FalseActionList</code> bestimmt (sofern <code>0..1</code> instantiiert). Das Enumerationsattribut <code>ActionListExecutionEnum</code> legt fest, ob die in <code>ActionList</code> enthaltenen <code>ActionItem</code>-Elemente bei jeder Auswertung (<code>triggeredOnEvaluation</code>) oder ausschließlich bei einer Statusänderung des Ergebnisses (<code>triggeredOnChange</code>) getriggert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die metamodellierte Konfigurationsstruktur für die Fehlerreaktion im Health Monitoring. Entwickler und Integratoren müssen sicherstellen, dass Regeln gültige Referenzen auf Aktionslisten (<code>0..1</code>) besitzen und das Triggerverhalten (<code>ActionListExecutionEnum</code>) passend zur geforderten Reaktionszeit und Systemlast (flankengetriggert vs. periodisch/auswertungsbasiert) parametriert wird.</p>"}], "trans": [{"from": "FIG-435aa6cd5894fb53", "to": "FIG-c22c3dab6dfed574", "fr": "R1.5.1", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c22c3dab6dfed574", "to": "FIG-435aa6cd5894fb53", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
